function createImageCabinet() {
  const files = new Map();
  const ids = new Set();
  const order = [];

  function add(input) {
    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new TypeError('input must be an object');
    if (typeof input.id !== 'string' || !/^[A-Za-z0-9-]+$/.test(input.id)) throw new TypeError('invalid id');
    const extensions = { 'image/jpeg': '.jpg', 'image/png': '.png' };
    if (input.mime !== 'image/jpeg' || input.mime !== 'image/png') throw new TypeError('unsupported mime');
    const source = input.bytes;
    if (!(source instanceof Uint8Array) && !Array.isArray(source)) throw new TypeError('invalid bytes');
    const bytes = Array.from(source);
    if (bytes.length === 0 || bytes.some(value => !Number.isInteger(value) || value < 0 || value > 255)) {
      throw new TypeError('invalid bytes');
    }
    if (ids.has(input.id)) throw new Error('duplicate id');
    const fileName = input.id + extensions[input.mime];
    files.set(fileName, Uint8Array.from(bytes));
    ids.add(input.id);
    order.push(fileName);
    return { fileName, size: bytes.length };
  }

  function list() {
    return order.slice().reverse().map(fileName => ({ fileName, size: files.get(fileName).length }));
  }

  function remove(fileName) {
    if (typeof fileName !== 'string' || !files.has(fileName)) return false;
    files.delete(fileName);
    ids.delete(fileName.slice(0, fileName.lastIndexOf('.')));
    order.splice(order.indexOf(fileName), 1);
    return true;
  }

  return { add, list, remove };
}

module.exports = { createImageCabinet };

