'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createImageCabinet']);
const cabinet = api.createImageCabinet();
assert.deepStrictEqual(Object.keys(cabinet).sort(), ['add', 'list', 'remove']);
assert.deepStrictEqual(cabinet.list(), []);

const jpegBytes = new Uint8Array([0, 127, 255]);
assert.deepStrictEqual(cabinet.add({ id: 'hero-1', mime: 'image/jpeg', bytes: jpegBytes }), {
  fileName: 'hero-1.jpg', size: 3
});
jpegBytes[0] = 99;
const pngBytes = [1, 2, 3, 4];
assert.deepStrictEqual(cabinet.add({ id: 'logo2', mime: 'image/png', bytes: pngBytes }), {
  fileName: 'logo2.png', size: 4
});
pngBytes.push(5);
assert.deepStrictEqual(cabinet.list(), [
  { fileName: 'logo2.png', size: 4 },
  { fileName: 'hero-1.jpg', size: 3 }
]);

const firstList = cabinet.list();
firstList.pop();
firstList[0].fileName = 'changed.png';
assert.deepStrictEqual(cabinet.list(), [
  { fileName: 'logo2.png', size: 4 },
  { fileName: 'hero-1.jpg', size: 3 }
]);
assert.strictEqual(Object.prototype.hasOwnProperty.call(cabinet.list()[0], 'bytes'), false);

assert.throws(() => cabinet.add({ id: 'hero-1', mime: 'image/png', bytes: [8] }));
assert.strictEqual(cabinet.list().length, 2);
const invalidAdds = [
  null,
  { id: '', mime: 'image/png', bytes: [1] },
  { id: 'bad_id', mime: 'image/png', bytes: [1] },
  { id: 'x', mime: 'image/gif', bytes: [1] },
  { id: 'x', mime: 'image/png', bytes: [] },
  { id: 'x', mime: 'image/png', bytes: [256] },
  { id: 'x', mime: 'image/png', bytes: [-1] },
  { id: 'x', mime: 'image/png', bytes: [1.5] },
  { id: 'x', mime: 'image/png', bytes: '123' }
];
for (const input of invalidAdds) {
  assert.throws(() => cabinet.add(input));
  assert.strictEqual(cabinet.list().length, 2);
}

assert.strictEqual(cabinet.remove('hero-1.png'), false);
assert.strictEqual(cabinet.remove(' hero-1.jpg'), false);
assert.strictEqual(cabinet.remove(null), false);
assert.strictEqual(cabinet.remove('hero-1.jpg'), true);
assert.strictEqual(cabinet.remove('hero-1.jpg'), false);
assert.deepStrictEqual(cabinet.list(), [{ fileName: 'logo2.png', size: 4 }]);

